#include<bits/stdc++.h>
using namespace std;

typedef long long ll;

int power(int a, int e)
{
    if (e == 0)
        return 1;
    return e == 1 ? a : a * power(a, e-1);
}

void answer(int a, int b)
{
    cout<< a << " + " << b << " = " << a+b << "\n";
}

void solve()
{
    int a, b, c, i, left, right, have;
    ll k;
    cin>> a >> b >> c >> k;

    bool good = false;
    for (i = power(10, a-1); i < power(10, a); ++i)
    {
        left = max(power(10, b-1), power(10, c-1) - i);
        right = min(power(10, b)-1, power(10, c)-1-i);
        if (left > right) continue;

        have = right-left+1;
        if (k <= have) {
            answer(i, left+k-1);
            good = true;
            break;
        }
        k -= have;
    }
    if (!good) cout<< -1 << "\n";
}

int main()
{
    int i, T = 1;
    cin>> T;
    while (T--)
        solve();
    return 0;
}

