#include <iostream>
#include <cmath>

using namespace std;

typedef long long ll;

int power(int base, int exponent) {
    return (exponent == 0) ? 1 : (exponent == 1) ? base : base * power(base, exponent - 1);
}

void displayResult(int num1, int num2) {
    cout << num1 << " + " << num2 << " = " << num1 + num2 << "\n";
}

void process() {
    int digitsA, digitsB, digitsC;
    ll target;
    cin >> digitsA >> digitsB >> digitsC >> target;

    bool found = false;
    for (ll num = power(10, digitsA - 1); num < power(10, digitsA); ++num) {
        ll lowerBound = max(power(10, digitsB - 1), power(10, digitsC - 1) - num);
        ll upperBound = min(power(10, digitsB) - 1, power(10, digitsC) - 1 - num);

        if (lowerBound > upperBound) continue;

        ll count = upperBound - lowerBound + 1;
        if (target <= count) {
            displayResult(num, lowerBound + target - 1);
            found = true;
            break;
        }
        target -= count;
    }

    if (!found) cout << -1 << "\n";
}

int main() {
    int testCases = 1;
    cin >> testCases;
    while (testCases--) process();
    return 0;
}
