point2D points[N], rot_points[N];

bool cmp_x(point2D a, point2D b) {return a.x < b.x;}
bool cmp_y(point2D a, point2D b) {return a.y < b.y;}

ll calculate_count_x(point2D points[], int n) {
    int i, j, cnt;
    ll sum = 0, tmp;

    for (i = 0; i < n-1;) {
        cnt = 0;
        j = i+1;
        while (j < n && points[j].x == points[i].x) {
            cnt++;
            j++;
        }
        if (cnt > 0) {
            tmp = ll(cnt);
            sum += tmp*(tmp+1);
        }
        i = j;
    }
    return sum;
}

ll calculate_count_y(point2D points[], int n) {
    int i, j, cnt;
    ll sum = 0, tmp;

    for (i = 0; i < n-1;) {
        cnt = 0;
        j = i+1;
        while (j < n && points[j].y == points[i].y) {
            cnt++;
            j++;
        }
        if (cnt > 0) {
            tmp = ll(cnt);
            sum += tmp*(tmp+1);
        }
        i = j;
    }
    return sum;
}

