{
    int n, i, j, cnt;
    ll x, y, sum=0;
    vector<int> ans;
    cin>> n;

    for (i = 0; i < n; i++) {
        cin>> x >> y;
        points[i].x = x;
        points[i].y = y;
        rot_points[i].x = x - y;
        rot_points[i].y = x + y;
    }

    sort(points, points+n, cmp_x);
    sum += calculate_count_x(points, n);
    sort(points, points+n, cmp_y);
    sum += calculate_count_y(points, n);

    sort(rot_points, rot_points+n, cmp_x);
    sum += calculate_count_x(rot_points, n);
    sort(rot_points, rot_points+n, cmp_y);
    sum += calculate_count_y(rot_points, n);
    cout<< sum << "\n";
}

