using ll = long long;
using Point2D = pair<ll, ll>;

const int MAX_POINTS = 200001;
Point2D points[MAX_POINTS];
Point2D rotated_points[MAX_POINTS];

bool compare_by_x(const Point2D& a, const Point2D& b) {
    return a.first < b.first;
}

bool compare_by_y(const Point2D& a, const Point2D& b) {
    return a.second < b.second;
}

ll count_duplicates(const Point2D points[], int n) {
    ll count = 0;
    for (int i = 0; i < n - 1;) {
        int duplicate_count = 1;
        while (i + 1 < n && points[i + 1] == points[i]) {
            duplicate_count++;
            i++;
        }
        if (duplicate_count > 1) {
            count += static_cast<ll>(duplicate_count) * (duplicate_count + 1) / 2;
        }
        i++;
    }
    return count;
}

void solve() {
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i) {
        ll x, y;
        cin >> x >> y;
        points[i] = {x, y};
        rotated_points[i] = {x - y, x + y};
    }

    sort(points, points + n, compare_by_x);
    count_duplicates(points, n);

    sort(points, points + n, compare_by_y);
    count_duplicates(points, n);

    sort(rotated_points, rotated_points + n, compare_by_x);
    count_duplicates(rotated_points, n);

    sort(rotated_points, rotated_points + n, compare_by_y);
    count_duplicates(rotated_points, n);
}

