#include <iostream>
#include <vector>

using namespace std;

bool isPrime(int n) {
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

void solve() {
    int n, m;
    cin >> n >> m;
    bool prime_n = isPrime(n);
    bool prime_m = isPrime(m);

    vector<vector<int>> arr(n + 1, vector<int>(m + 1));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            arr[i][j] = i * m + j;
        }
    }

    if (!prime_m) {
        for (const auto& row : arr) {
            for (int val : row) {
                cout << val << " ";
            }
            cout << endl;
        }
    } else if (prime_n && prime_m) {
        for (int i = 1; i <= n; i += 2) {
            for (int j = 1; j <= m; ++j) {
                cout << arr[i][j] << " ";
            }
            cout << endl;
        }
        for (int i = 2; i <= n; i += 2) {
            for (int j = 1; j <= m; ++j) {
                cout << arr[i][j] << " ";
            }
            cout << endl;
        }
    } else {
        for (int i = 1; i <= n; ++i) {
            for (int j = i; j <= m; j += n) {
                cout << arr[j / n + 1][j % n + 1] << " ";
            }
            cout << endl;
        }
    }
}

